// Settled before it is ever bridged: the adoption has nothing to wait for.
module.exports.settled = function settled(value) {
  return Promise.resolve(value * 2);
};

// Settled only by an ENGINE timer, which rides the native timer heap: the
// bridge must leave this pending and let the loop deliver it.
module.exports.later = function later(ms, value) {
  return new Promise((resolve) => setTimeout(() => resolve(value * 2), ms));
};

// Rejected by an engine timer, with a real Error subclass so the static
// side can narrow it.
module.exports.failLater = function failLater(ms, message) {
  return new Promise((_, reject) => setTimeout(() => reject(new TypeError(message)), ms));
};

// Nothing can ever settle this one, and it arms no timer: awaiting it
// abandons the fiber and the loop exhausts.
module.exports.never = function never() {
  return new Promise(() => {});
};
